212	    private void flushRotationRecord(RefreshTokenContext ctx, RefreshToken newRefreshToken) {
213	        //Retrieve the staged token from in-memory fields and immediately clear them
214	        String key = pendingRotationKey;
215	        Map<String, String> record = pendingRotationRecord;
216	
217	        pendingRotationKey = null;
218	        pendingRotationRecord = null;
219	
220	        if (key == null || record == null) {
221	            return;
222	        }
223	
224	        // Complete the record with newly generated child token's metadata
225	        RefreshToken lifespanSource = ctx.oldRefreshToken();
226	        if (newRefreshToken != null) {
227	            // Record new Refresh token as the most recent valid child in the family
228	            record.put(NOTE_LATEST_GENERATED_TOKEN_ID, newRefreshToken.getId());
229	            record.put(NOTE_LAST_REFRESH, String.valueOf(newRefreshToken.getIat()));
230	            lifespanSource = newRefreshToken;
231	        }
232	        // Completes the read-modify-write started in validateTokenReuseForRefresh. It is atomic because
233	        // getRefreshTokenLockId() keys the refresh lock on the same family key as the record, and that lock is only
234	        // released once this transaction has committed.
235	        storeRotationRecord(session.singleUseObjects(), key, lifespanSource, record);
236	    }
