240	        // Revoke the issued verifiable credential associated with this refresh token
241	        List<AuthorizationDetailsJSONRepresentation> authorizationDetails = token.getAuthorizationDetails();
242	        if (authorizationDetails == null || authorizationDetails.isEmpty()) {
243	            logger.warnf("OID4VCI refresh token revoked but authorization_details is missing. " +
244	                            "Realm: %s, client: %s, user: %s",
245	                    session.getContext().getRealm().getName(), client.getClientId(), user.getUsername());
246	            return;
247	        }
248	
249	        for (AuthorizationDetailsJSONRepresentation detail : authorizationDetails) {
250	            if (!OPENID_CREDENTIAL.equals(detail.getType())) {
251	                continue;
252	            }
