271	                        issuedCredentialId, session.getContext().getRealm().getName(), client.getClientId(), user.getUsername());
272	                continue;
273	            }
274	
275	            logger.debugf("Removed issued verifiable credential '%s' on refresh token revocation. " +
276	                            "Realm: %s, client: %s, user: %s",
277	                    issuedCredentialId, session.getContext().getRealm().getName(),
278	                    client.getClientId(), user.getUsername());
