298	    /**
299	     * The client session created in {@link #validateToken} is TRANSIENT, so it is discarded at the end of the request
300	     * and the rotation state the default implementation keeps on it is always empty. Keep the equivalent state in the
301	     * single-use object store instead, keyed by the refresh token family.
302	     * <p>
303	     * Mirrors the logic of {@link TokenManager#validateTokenReuse}.
304	     * The updated record is only staged here and written once in {@link #flushRotationRecord}, which also knows the id of the newly generated token.
305	     */
306	    @Override
307	    protected void validateTokenReuseForRefresh(KeycloakSession session, RealmModel realm, RefreshToken refreshToken, TokenManager.TokenValidation validation, TokenManager tokenManager) throws OAuthErrorException {
308	        pendingRotationKey = null;
309	        pendingRotationRecord = null;
310	
311	        if (!realm.isRevokeRefreshToken()) {
312	            return;
313	        }
314	
315	        if (refreshToken.getExp() == null) {
316	            throw new OAuthErrorException(OAuthErrorException.INVALID_GRANT, "Invalid refresh token", "Refresh token has no expiration");
317	        }
318	
319	        String key = getRotationKey(realm, refreshToken);
320	        Map<String, String> record = session.singleUseObjects().get(key);
321	
322	        String acceptedTokenId = getNote(record, NOTE_ACCEPTED_TOKEN_ID);
323	        String latestGeneratedTokenId = getNote(record, NOTE_LATEST_GENERATED_TOKEN_ID);
324	        int useCount = getIntNote(record, NOTE_USE_COUNT);
325	        int lastRefresh = getIntNote(record, NOTE_LAST_REFRESH);
326	
327	        if (acceptedTokenId != null && !refreshToken.getId().equals(acceptedTokenId)) {
328	            // A different token of this family was already accepted. Anything issued no later than the most recently
329	            // generated token is a replay of an already rotated token.
330	            if (latestGeneratedTokenId != null && !refreshToken.getId().equals(latestGeneratedTokenId) && refreshToken.getIat() <= lastRefresh) {
331	                logger.debugf("Rejecting replayed oid4vci refresh token %s. Realm: %s, client: %s",
332	                        refreshToken.getId(), realm.getName(), session.getContext().getClient().getClientId());
333	                throw new OAuthErrorException(OAuthErrorException.INVALID_GRANT, "Stale token");
334	            }
335	            // Strictly newer token: it becomes the accepted one and its reuse counter starts over
336	            useCount = 0;
337	        }
338	
339	        if (useCount > realm.getRefreshTokenMaxReuse()) {
340	            logger.debugf("Rejecting oid4vci refresh token %s due to exceeding max reuse count. Realm: %s, client: %s",
341	                    refreshToken.getId(), realm.getName(), session.getContext().getClient().getClientId());
342	            throw new OAuthErrorException(OAuthErrorException.INVALID_GRANT, "Maximum allowed refresh token reuse exceeded",
343	                    "Maximum allowed refresh token reuse exceeded");
344	        }
345	
346	        Map<String, String> updated = record == null ? new HashMap<>() : new HashMap<>(record);
347	        updated.put(NOTE_ACCEPTED_TOKEN_ID, refreshToken.getId());
348	        updated.put(NOTE_USE_COUNT, String.valueOf(useCount + 1));
349	        pendingRotationKey = key;
350	        pendingRotationRecord = updated;
351	    }
