353	    private void storeRotationRecord(SingleUseObjectProvider singleUseStore, String key, RefreshToken refreshToken, Map<String, String> record) {
354	        Long expiration = refreshToken.getExp();
355	        long lifeSpan = (expiration == null ? 0 : expiration - Time.currentTimeSeconds()) + ROTATION_RECORD_CLOCK_SKEW_SECONDS;
356	        if (lifeSpan <= 0) {
357	            return; // already expired, it can never be successfully replayed anyway
358	        }
359	        singleUseStore.put(key, lifeSpan, record);
360	    }
