371	    /**
372	     * The reuse_id claim is generated once per refresh token family and copied onto every rotated token, so it
373	     * identifies the whole chain. Tokens issued before revoke-refresh-token was enabled have none, in which case this
374	     * degrades to strict single-use of that one token.
375	     */
376	    private String getRotationKey(RealmModel realm, RefreshToken refreshToken) {
377	        Object reuseId = refreshToken.getOtherClaims().get(Constants.REUSE_ID);
378	        String familyId = reuseId != null ? String.valueOf(reuseId) : refreshToken.getId();
379	        return ROTATION_KEY_PREFIX + HashUtils.sha256UrlEncodedHash(realm.getId() + "." + familyId, StandardCharsets.UTF_8);
380	    }
