99	    @Override
100	    public OID4VCAuthorizationDetail validateAuthorizationDetail(AuthorizationDetailsJSONRepresentation authzDetail) throws InvalidAuthorizationDetailsException {
101	
102	        OID4VCAuthorizationDetail requestAuthDetail = authzDetail.asSubtype(OID4VCAuthorizationDetail.class);
103	
104	        CredentialIssuer issuerMetadata = new OID4VCIssuerWellKnownProvider(session).getIssuerMetadata();
105	        Map<String, SupportedCredentialConfiguration> supportedCredentials = issuerMetadata.getCredentialsSupported();
106	        List<String> authorizationServers = issuerMetadata.getAuthorizationServers();
107	        String issuerIdentifier = issuerMetadata.getCredentialIssuer();
108	
109	        String type = requestAuthDetail.getType();
110	        String credentialConfigurationId = requestAuthDetail.getCredentialConfigurationId();
111	        List<String> credentialIdentifiers = requestAuthDetail.getCredentialIdentifiers();
112	        List<ClaimsDescription> claims = requestAuthDetail.getClaims();
113	
114	        // Validate type first
115	        if (!OPENID_CREDENTIAL.equals(type)) {
116	            logger.warnf("Invalid authorization_details type: %s", type);
117	            throw getInvalidRequestException("type: " + type + ", expected=" + OPENID_CREDENTIAL);
118	        }
119	
120	        // If authorization_servers is present, locations must be set to issuer identifier
121	        if (authorizationServers != null && !authorizationServers.isEmpty()) {
122	            List<String> locations = requestAuthDetail.getLocations();
123	            if (locations == null || locations.size() != 1 || !issuerIdentifier.equals(locations.get(0))) {
124	                logger.warnf("Invalid locations field in authorization_details: %s, expected: %s", locations, issuerIdentifier);
125	                throw getInvalidRequestException("locations=" + locations + ", expected=" + issuerIdentifier);
126	            }
127	        }
128	
129	        // credential_configuration_id is REQUIRED
130	        if (Strings.isEmpty(credentialConfigurationId)) {
131	            logger.warnf("Missing credential_configuration_id in authorization_details");
132	            throw getInvalidRequestException("credential_configuration_id is required");
133	        }
134	
135	        // credential_identifiers not allowed
136	        if (credentialIdentifiers != null) {
137	            // we also reject an empty array of credential identifiers
138	            logger.warnf("Property credential_identifiers not allowed in authorization_details");
139	            throw getInvalidRequestException("credential_identifiers not allowed");
140	        }
141	
142	        // Issued credential ID not allowed
143	        if (requestAuthDetail.getIssuedCredentialId() != null) {
144	            logger.warnf("Property '%s' not allowed in authorization_details", ISSUED_CREDENTIAL_ID);
145	            throw getInvalidRequestException("Issued credential ID not allowed in authorization details");
146	        }
147	
148	        // Validate credential_configuration_id
149	        SupportedCredentialConfiguration credConfig = supportedCredentials.get(credentialConfigurationId);
150	        if (credConfig == null) {
151	            logger.warnf("Unsupported credential_configuration_id: %s", credentialConfigurationId);
152	            throw getInvalidRequestException("Invalid credential configuration: unsupported credential_configuration_id: " + credentialConfigurationId);
153	        }
154	
155	        // Validate claims if present
156	        if (claims != null && !claims.isEmpty()) {
157	            validateClaims(claims, credConfig);
158	        }
159	
160	        return requestAuthDetail;
161	    }
