179	    /**
180	     * Validates that the requested claims are supported by the credential configuration.
181	     * This performs semantic validation by checking if Keycloak supports the requested claims.
182	     *
183	     * @param claims the list of claims to validate
184	     * @param config the credential configuration to validate against
185	     */
186	    private void validateClaims(List<ClaimsDescription> claims, SupportedCredentialConfiguration config) {
187	
188	        // Get the exposed claims from credential metadata
189	        List<Claim> exposedClaims = null;
190	        if (config.getCredentialMetadata() != null && config.getCredentialMetadata().getClaims() != null && !config.getCredentialMetadata().getClaims().isEmpty()) {
191	            exposedClaims = config.getCredentialMetadata().getClaims();
192	        }
193	
194	        if (exposedClaims == null || exposedClaims.isEmpty()) {
195	            throw getInvalidRequestException("Credential configuration does not expose any claims metadata");
196	        }
197	
198	        // Convert exposed claims to a set of paths for easy comparison
199	        Set<String> exposedClaimPaths = exposedClaims.stream()
200	                .filter(claim -> claim.getPath() != null && !claim.getPath().isEmpty())
201	                .map(claim -> claim.getPath().toString())
202	                .collect(Collectors.toSet());
203	
204	        // Validate each requested claim against exposed metadata
205	        for (ClaimsDescription requestedClaim : claims) {
206	            if (requestedClaim.getPath() == null || requestedClaim.getPath().isEmpty()) {
207	                throw getInvalidRequestException("Invalid claims description: path is required");
208	            }
209	
210	            // Validate the claims path pointer format according to OID4VCI specification
211	            if (!ClaimsPathPointer.isValidPath(requestedClaim.getPath())) {
212	                throw getInvalidRequestException("Invalid claims path pointer: " + requestedClaim.getPath() +
213	                        ". Path must contain only strings, non-negative integers, and null values.");
214	            }
215	
216	            String requestedPath = requestedClaim.getPath().toString();
217	
218	            // Check if the requested claim path exists in the exposed metadata
219	            if (!exposedClaimPaths.contains(requestedPath)) {
220	                throw getInvalidRequestException("Unsupported claim: " + requestedPath +
221	                        ". This claim is not supported by the credential configuration.");
222	            }
223	        }
224	
225	        // Check for conflicts using ClaimsPathPointer utility
226	        if (!ClaimsPathPointer.validateClaimsDescriptions(claims)) {
227	            throw getInvalidRequestException("Invalid claims descriptions: conflicting or contradictory claims found");
228	        }
229	    }
