231	    private OID4VCAuthorizationDetail buildAuthorizationDetailResponse(ClientSessionContext clientSessionCtx, OID4VCAuthorizationDetail requestAuthDetail) {
232	
233	        String requestedCredentialConfigurationId = requestAuthDetail.getCredentialConfigurationId();
234	        if (requestedCredentialConfigurationId == null) {
235	            throw getInvalidRequestException("No credential_configuration_id in access token request.");
236	        }
237	
238	        // Handle AccessToken request with credential offer
239	        // Should work for pre-auth and auth-code grants
240	        //
241	        CredentialOfferState offerState = getCredentialOfferState(clientSessionCtx);
242	        if (offerState != null) {
243	            OID4VCAuthorizationDetail offeredAuthDetail = offerState.getAuthorizationDetails(requestedCredentialConfigurationId);
244	            if (offeredAuthDetail == null) {
245	                throw getInvalidRequestException("Unauthorized credential_configuration_id: " + requestedCredentialConfigurationId);
246	            }
247	            OID4VCAuthorizationDetail responseAuthDetail = offeredAuthDetail.clone();
248	            responseAuthDetail.setClaims(requestAuthDetail.getClaims());
249	            return responseAuthDetail;
250	        }
251	
252	        // Handle AccessToken request without credential offer
253	        //
254	        RealmModel realmModel = clientSessionCtx.getClientSession().getRealm();
255	        CredentialScopeModel credScope = findCredentialScopeModelByConfigurationId(realmModel, clientSessionCtx::getClientScopesStream, requestedCredentialConfigurationId);
256	        if (credScope == null)
257	            throw getInvalidRequestException("Cannot find or access client scope for credential_configuration_id: " + requestedCredentialConfigurationId);
258	
259	        UserModel user = clientSessionCtx.getClientSession().getUserSession().getUser();
260	        if (!OID4VCUtil.hasVerifiableCredential(session, user, credScope)) {
261	            throw getInvalidRequestException("User '" + user.getUsername() + "' does not have verifiable credential '" + credScope.getCredentialConfigurationId() + "'.");
262	        }
263	
264	        OID4VCAuthorizationDetail responseAuthDetail = generateResponseAuthorizationDetails(credScope, null);
265	        responseAuthDetail.setClaims(requestAuthDetail.getClaims());
266	
267	        return responseAuthDetail;
268	    }
