270	    @Override
271	    public List<OID4VCAuthorizationDetail> handleMissingAuthorizationDetails(UserSessionModel userSession, ClientSessionContext clientSessionCtx) {
272	        RealmModel realmModel = userSession.getRealm();
273	
274	        // AccessToken request with credential offer
275	        // Works for pre-auth and auth-code grants
276	        CredentialOfferState offerState = getCredentialOfferState(clientSessionCtx);
277	        if (offerState != null) {
278	            return offerState.getAuthorizationDetails();
279	        }
280	
281	        // AccessToken request with no credential offer and no auth details
282	        // This is likely a "scope only" request
283	        String scopeParam = clientSessionCtx.getScopeString();
284	        if (scopeParam == null) {
285	            throw getInvalidRequestException("No 'scope' parameter in client session");
286	        }
287	
288	        List<OID4VCAuthorizationDetail> authorizationDetails = new ArrayList<>();
289	        for (String scope : scopeParam.split(" ")) {
290	            CredentialScopeModel credScope = findCredentialScopeModelByName(realmModel, clientSessionCtx::getClientScopesStream, scope);
291	            if (credScope != null) {
292	                if (!OID4VCUtil.hasVerifiableCredential(session, userSession.getUser(), credScope)) {
293	                    throw getInvalidRequestException("User '" + userSession.getUser().getUsername() + "' does not have verifiable credential '" + credScope.getCredentialConfigurationId() + "'.");
294	                }
295	
296	                // Generate `authorization_details` for the AccessToken Response
297	                // This is the same logic as we use when a credential offer is created
298	                //
299	                OID4VCAuthorizationDetail authDetail = generateResponseAuthorizationDetails(credScope, null);
300	                authorizationDetails.add(authDetail);
301	            }
302	        }
303	
304	        if (!authorizationDetails.isEmpty()) {
305	            logger.debugf("Generated authorization_details: %s", JsonSerialization.valueAsString(authorizationDetails));
306	        } else {
307	            logger.debug("No generated authorization_details");
308	        }
309	        return authorizationDetails;
310	    }
