312	    @Override
313	    public OID4VCAuthorizationDetail processStoredAuthorizationDetails(UserSessionModel userSession, ClientSessionContext clientSessionCtx, AuthorizationDetailsJSONRepresentation storedAuthDetails)
314	            throws InvalidAuthorizationDetailsException {
315	        if (storedAuthDetails == null) {
316	            return null;
317	        }
318	
319	        logger.debugf("Processing stored authorization_details from authorization request: %s", storedAuthDetails);
320	
321	        try {
322	            return process(userSession, clientSessionCtx, storedAuthDetails);
323	        } catch (InvalidAuthorizationDetailsException e) {
324	            // According to OID4VC spec, if authorization_details was used in authorization request,
325	            // it is required to be returned in token response. If it cannot be processed, return invalid_request error
326	            throw new InvalidAuthorizationDetailsException("authorization_details was used in authorization request but cannot be processed for token response: " + e.getMessage());
327	        }
328	    }
