355	    public OID4VCAuthorizationDetail generateResponseAuthorizationDetails(CredentialScopeModel credScope, String credOffersId) {
356	
357	        OID4VCAuthorizationDetail authDetail = new OID4VCAuthorizationDetail();
358	        authDetail.setCredentialsOfferId(credOffersId);
359	        authDetail.setType(OPENID_CREDENTIAL);
360	
361	        String credConfigId = Optional.ofNullable(credScope.getCredentialConfigurationId())
362	                .orElseThrow(() -> new IllegalStateException("No " + VC_CONFIGURATION_ID + " in client scope: " + credScope.getName()));
363	
364	        authDetail.setCredentialConfigurationId(credConfigId);
365	
366	        // The AccessToken Response should have authorization_details when ...
367	        //
368	        //  * provided in Authorization Request
369	        //  * provided in AccessToken Request
370	        //  * defined credential identifiers
371	        //
372	        // https://gitlab.com/openid/conformance-suite/-/work_items/1724
373	
374	        String credIdentifier = credScope.getCredentialIdentifier();
375	        if (Strings.isEmpty(credIdentifier)) {
376	            credIdentifier = credConfigId + "_0000";
377	        }
378	        authDetail.setCredentialIdentifiers(List.of(credIdentifier));
379	
380	        return authDetail;
381	    }
