383	    protected IssuedVerifiableCredentialModel createIssuedVerifiableCredential(UserModel userModel, ClientModel clientModel, CredentialScopeModel credentialScope) {
384	        String credentialScopeName = credentialScope.getName();
385	        try {
386	            // Lookup the UserVerifiableCredential by client scope ID to get its ID
387	            UserVerifiableCredentialModel verifiableCredential = session.users()
388	                    .getVerifiableCredentialByClientScope(userModel.getId(), credentialScope.getId());
389	            if (verifiableCredential == null) {
390	                throw new ModelException("User verifiable credential not found for scope: " + credentialScopeName);
391	            }
392	
393	            IssuedVerifiableCredentialModel model = new IssuedVerifiableCredentialModel(userModel.getId(), verifiableCredential.getId(), clientModel.getId());
394	
395	            long issuedAt = Time.currentTimeMillis();
396	            model.setIssuedAt(issuedAt);
397	            model.setExpiresAt(issuedAt + (credentialScope.getExpiryInSeconds() * 1000L));
398	
399	            logger.debugf("Created VC issuance: user=%s, client=%s, type=%s", userModel.getUsername(), clientModel.getClientId(), credentialScopeName);
400	
401	            return session.users().addIssuedVerifiableCredential(model);
402	        } catch (Exception e) {
403	            throw new ModelException(String.format("Failed to create VC issuance for user=%s, client=%s, type=%s", userModel.getUsername(), clientModel.getClientId(), credentialScopeName), e);
404	        }
405	    }
