409	    private CredentialOfferState getCredentialOfferState(ClientSessionContext clientSessionCtx) {
410	
411	        CredentialOfferState offerState = null;
412	
413	        // Check if we have a credential offer - this should work for pre-authorized
414	        //
415	        String credOfferId = clientSessionCtx.getAttribute(CREDENTIALS_OFFER_ID_ATTR, String.class);
416	
417	        // Check if we have issuer_state - this should work for authorization_code
418	        //
419	        String issuerStateNote = clientSessionCtx.getClientSession().getNote(LOGIN_SESSION_NOTE_ADDITIONAL_REQ_PARAMS_PREFIX + ISSUER_STATE);
420	        if (credOfferId == null && issuerStateNote != null) {
421	            IssuerState issuerState = IssuerState.fromEncodedString(issuerStateNote);
422	            credOfferId = issuerState.getCredentialsOfferId();
423	        }
424	
425	        if (credOfferId != null) {
426	            String auxCredOfferId = credOfferId;
427	            CredentialOfferStorage offerStorage = session.getProvider(CredentialOfferStorage.class);
428	            offerState = Optional.ofNullable(offerStorage.getOfferStateById(credOfferId))
429	                    .orElseThrow(() -> new IllegalStateException("No credential offer state for: " + auxCredOfferId));
430	
431	            // Check same login client as the client for which the credential offer is target (in case of credential offer target for specific client only)
432	            String offerClientId = offerState.getTargetClientId();
433	            String loginClientId = clientSessionCtx.getClientSession().getClient().getClientId();
434	            if (offerClientId != null && !offerClientId.equals(loginClientId)) {
435	                throw new IllegalStateException("Credential offer target client '" + offerClientId + "' different from login client '" + loginClientId + "'");
436	            }
437	        }
438	
439	        return offerState;
440	    }
